public sealed class MetadatosApiTests
{
    private const int SalidaPorLlamada = 200;
    private const decimal PrecioEntrada = 1.0m;
    private const decimal PrecioSalida = 5.0m;
    private const decimal ToleranciaDeCosto = 0.000001m;

    private static void AfirmarConsumo(RespuestaApi respuesta, ClienteLlmDoble llm)
    {
        var entrada = llm.Solicitudes.Sum(ConsumoRealista.Reportados);
        var salida = llm.Llamadas * SalidaPorLlamada;
        var costo = ConsumoRealista.CostoDe(entrada, salida, PrecioEntrada, PrecioSalida);
        Assert.Equal(entrada + salida, respuesta.Tokens);
        Assert.InRange(respuesta.CostoUsd, costo - ToleranciaDeCosto, costo + ToleranciaDeCosto);
    }

    public static TheoryData<string, string, bool> UsoDeDatos => new()
    {
        { "EST-001", "¿Cómo se calcula la nota definitiva de una asignatura?", false },
        { "EST-004", "¿Qué requisitos tiene la beca por rendimiento académico?", false },
        { "EST-004", "¿Qué nota definitiva tengo en Contabilidad?", true }
    };

    [Fact]
    [Trait("CA", "CA-11")]
    public async Task Costo_se_calcula_con_los_precios_configurados()
    {
        var llm = ClienteLlmDoble.Texto("Respuesta de prueba.", new UsoTokens(0, SalidaPorLlamada));
        using var fabrica = new FabricaApi(llm: llm, configuracion: FabricaApi.Precios("1.0", "5.0"));

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio?");

        Assert.Equal(200, respuesta.Estado);
        AfirmarConsumo(respuesta, llm);
    }

    [Fact]
    [Trait("CA", "CA-11")]
    [Trait("ESC", "ESC-106")]
    public async Task ESC_106_Tokens_y_costo_suman_todas_las_invocaciones_al_llm()
    {
        var llm = ClienteLlmDoble.ConsultaDatos(uso: new UsoTokens(0, SalidaPorLlamada));
        using var fabrica = new FabricaApi(llm: llm, configuracion: FabricaApi.Precios("1.0", "5.0"));

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio ponderado del periodo?");

        Assert.Equal(200, respuesta.Estado);
        AfirmarConsumo(respuesta, llm);
    }

    [Fact]
    [Trait("CA", "CA-11")]
    [Trait("ESC", "ESC-106")]
    public async Task ESC_106_El_403_previo_reporta_tokens_y_costo_cero()
    {
        using var fabrica = new FabricaApi(configuracion: FabricaApi.Precios("1.0", "5.0"));

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuáles son las notas de EST-002?");

        Assert.Equal(0, respuesta.Tokens);
        Assert.Equal(0m, respuesta.CostoUsd);
    }

    [Theory]
    [MemberData(nameof(UsoDeDatos))]
    [Trait("CA", "CA-11")]
    [Trait("SEG", "COMP-04")]
    public async Task Uso_datos_estudiante_es_verdadero_solo_si_se_leyeron_datos(string id, string pregunta, bool esperado)
    {
        var llm = esperado ? ClienteLlmDoble.ConsultaDatos() : ClienteLlmDoble.Texto("Respuesta normativa.");
        using var fabrica = new FabricaApi(llm: llm);

        var respuesta = await fabrica.PreguntarEstudianteAsync(id, pregunta);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(esperado, respuesta.UsoDatosEstudiante);
        Assert.Equal(esperado, fabrica.Api.Llamadas.Any(l => l.StartsWith("ObtenerNotas", StringComparison.Ordinal)));
    }
}
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;
using TutorFlow.Pruebas.Soporte;

namespace TutorFlow.Api.Tests.Contrato;

public sealed class NormativaDelCoordinadorApiTests
{
    private const string Pregunta = "¿Quién puede consultar la información académica de un estudiante?";
    private const string FuenteDelPrograma = "fuente=\"Datos del programa";
    private const string TextoSinReferencia = "Pueden consultarla el propio estudiante y el coordinador de su programa.";

    public static TheoryData<string, string> RespuestasDelDoble => new()
    {
        { "a", $"{TextoSinReferencia[..^1]} (reglamento_academico_2025.md · Artículo 22)." },
        { "b", TextoSinReferencia }
    };

    [Theory]
    [MemberData(nameof(RespuestasDelDoble))]
    [Trait("CA", "CA-14")]
    [Trait("CA", "CA-19")]
    [Trait("ESC", "ESC-018")]
    [Trait("D", "D-66")]
    public async Task ESC_018ab_La_pregunta_normativa_del_coordinador_cita_exactamente_el_articulo_22_sin_prelectura_y_con_uso_false(string caso, string texto)
    {
        Assert.NotEmpty(caso);
        using var fabrica = new FabricaApi(llm: GuionesLlm.SinHerramientas(_ => texto), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarCoordinadorAsync("COORD-01", Pregunta);

        Assert.Equal(200, respuesta.Estado);
        Assert.Contains("coordinador", respuesta.Respuesta, StringComparison.Ordinal);
        Assert.Equal(["reglamento_academico_2025.md · Artículo 22"], respuesta.Citas);
        Assert.False(respuesta.UsoDatosEstudiante);
        Assert.All(fabrica.Llm.Solicitudes.SelectMany(s => s.Mensajes), m => Assert.DoesNotContain(FuenteDelPrograma, m.Contenido, StringComparison.Ordinal));
        Assert.DoesNotContain(fabrica.Api.Llamadas, l => l.StartsWith("ObtenerNotas", StringComparison.Ordinal) || l.StartsWith("ObtenerAsistencia", StringComparison.Ordinal));
    }
}
